select r.RVI_NMRO_ITEM, p.POL_PRS_NMRO_IDNTFCCION
from rsgos_vgntes r, plzas p
where r.RVI_NMRO_PLZA = p.POL_NMRO_PLZA
and p.POL_NMRO_PLZA < 999
and r.RVI_FCHA_DSDE_ACTUAL > to_date('01/01/2024', 'dd/mm/yyyy');

select * from INDEMNIZA.LISTA_DOCUMENTO where sini_sol_sai_solicitud in (5342909,7710679,6554598,6437619,6644215) order by SINI_SOL_SAI_SOLICITUD;

select * from INDEMNIZA.SINIESTRO;

select l.*, d.*
from LISTA_DOCUMENTO l
         inner join documento_temporal d
                    on l.sini_sol_sai_solicitud = d.NUMEROSOLICITUD and l.COD_DOC = d.COD_DOC;

select count(*)
from LISTA_DOCUMENTO l
         inner join documento_temporal d
                    on l.sini_sol_sai_solicitud = d.NUMEROSOLICITUD and l.COD_DOC = d.COD_DOC;


select
    'docfilenet.extend;' || chr(10) ||
    'docfilenet(' || rownum || ') := ty_reg_filenet(''' ||
    d.COD_DOC || ''',''' ||
    d.NUMEROSOLICITUD || ''',''' ||
    l.RUTA_REPO || ''');'
        as linea_plsql
from LISTA_DOCUMENTO l
         inner join DOCUMENTO_TEMPORAL d
                    on l.sini_sol_sai_solicitud = d.NUMEROSOLICITUD and l.COD_DOC = d.COD_DOC;

select d.fecharecepciondocumento, l.SINI_SOL_SAI_SOLICITUD
from LISTA_DOCUMENTO l
         inner join documento_temporal d
                    on l.sini_sol_sai_solicitud = d.NUMEROSOLICITUD and l.COD_DOC = d.COD_DOC
where l.SINI_SOL_SAI_SOLICITUD = 4989324;

select d.fecharecepciondocumento, d.NUMEROSOLICITUD, d.*
from documento_temporal d
where NUMEROSOLICITUD = 6594318;

select d.fecharecepciondocumento, d.NUMEROSOLICITUD, d.*
from documento_temporal d
where NUMEROSOLICITUD = 11201579;

Select count(*) from documento_temporal;

select *
from INDEMNIZA.LISTA_DOCUMENTO
where SINI_SOL_SAI_SOLICITUD IN
      (5342909,7710679,6554598,6437619,6644215);

                  select
    'docfilenet.extend;' || chr(10) ||
    'docfilenet(' || rownum || ') := ty_reg_filenet(''' ||
    d.COD_DOC || ''',''' ||
    d.NUMEROSOLICITUD || ''',''{0051F571-0000-C046-BD54-D700EEAE92A5}'');'
    as linea_plsql
from documento_temporal d;

SELECT d.*
FROM documento_temporal d
         LEFT JOIN LISTA_DOCUMENTO l ON d.NUMEROSOLICITUD = l.sini_sol_sai_solicitud AND d.COD_DOC = l.COD_DOC
WHERE l.sini_sol_sai_solicitud IS NULL;


